it.each(['revision','masked-content'] as const)('fresh source reread refuses changed %s after the first real signed read',async kind=>{
 const f=await fresh();let changed=false;f.signed.document.afterRead(async()=>{if(changed)return;changed=true;await f.signed.document.configure(kind==='revision'?{revision:'synthetic-r2'}:{text:syntheticDocumentText.replace(syntheticDocumentSecret,syntheticDocumentSecret.slice(0,-1)+'X')});});await f.denied(f.execute());expect(changed).toBe(true);expect(f.signed.document.calls.length).toBeGreaterThanOrEqual(2);
});
it('Gateway business request reuse keeps one action but fresh-guards source; new request differs from protocol nonce replay',async()=>{
 const f=await fresh(),args=f.args(),first=await f.execute(args);expect(first.status).toBe('OK');const prior=f.signed.document.calls.length;expect((await f.execute(args)).status).toBe('OK');expect((await f.actions()).length).toBe(1);expect(f.signed.document.calls.length).toBeGreaterThan(prior);expect((await f.execute()).status).toBe('OK');expect((await f.actions()).length).toBe(2);
 const request=await f.signed.request(),envelope=f.signed.sign(request),before=f.signed.document.calls.length,replies=await Promise.all([f.signed.rawRead(envelope),f.signed.rawRead(envelope)]);expect(replies.filter(x=>x.result.ok)).toHaveLength(1);expect(replies.find(x=>!x.result.ok)!.result).toEqual({ok:false,code:'DWS_RPC_REPLAY'});expect(f.signed.document.calls.length).toBe(before+1);expect((await f.actions()).length).toBe(2);await f.noOutput();
},30000);
