 const callerFile=join(signed.root,'formal-caller.pem'),runnerFile=join(signed.root,'formal-runner.pem'),configFile=join(signed.root,'formal-document.json');
 await writeFile(callerFile,signed.caller.privateKey.export({type:'pkcs8',format:'pem'}),{mode:0o600});await writeFile(runnerFile,signed.signer.publicKey.export({type:'spki',format:'pem'}),{mode:0o600});await writeFile(configFile,JSON.stringify({schemaVersion:1,mode:'SIGNED_DOCUMENT_READ_V1',executionMode:'SYNTHETIC_TEST',reviewed:true,reviewReference:'SYNTHETIC_FORMAL_DOCUMENT_ONLY',socketPath:signed.socketPath,callerKeyId:signed.policy.callerKeyId,callerPrivateKeyFile:callerFile,runnerKeyId:signed.policy.runnerKeyId,runnerPublicKeyFile:runnerFile,bindingHash:signed.service.bindingHash,policyHash:signed.policy.policyHash,timeoutMs:3000,maxOutputBytes:128000,binaryHash:signed.scope.binaryHash,schemaHash:signed.document.runner.config.schemaHash,documentSchemaHash:signed.scope.documentSchemaHash,documentScopes:[signed.scope]}),{mode:0o600});
 const configured=await configureDws(formalDb,vault,{DWS_ENABLED:'true',DWS_RUNNER_CONFIG_FILE:configFile}),formalStore=new RuntimeStore(formalDb,vault),gateway=new Gateway(formalStore);registerDwsCapabilities(gateway,configured);const descriptor=gateway.describeCapability('dws.doc.read','1.0.0')!;
 await root.query("UPDATE capability_bindings SET schema_hash=$2 WHERE tenant_id=$1 AND logical_id='dws.doc.read'",[base.ctx.tenantId,descriptor.bindingHash]);
 const conversationId='synthetic-doc-dm-'+base.ctx.actorId,budgetPolicyHash=hash(JSON.stringify(JSON.parse(await readFile(process.env['BUDGET_POLICY_FILE']!,'utf8'))));
 const trial=trialProfileSchema.parse({schemaVersion:1,...base.ctx,corpId:base.subject.corpId,externalUserId:base.subject.userId,robotCode:base.binding.robotCode,conversationId,deadline:new Date(Date.now()+3600000).toISOString(),budgetPolicyHash,approvalReference:'SYNTHETIC_DOCUMENT_TRIAL_ONLY'}),trialHash=hash(JSON.stringify(trial));
